import { CreateDateColumn, PrimaryColumn, UpdateDateColumn } from 'typeorm';

/**
 * Base for every entity: UUIDv7 primary key generated by PostgreSQL 18's native uuidv7()
 * (time-ordered, so inserts stay index-friendly), plus created/updated timestamps.
 * TypeORM returns the generated id via INSERT ... RETURNING.
 */
export abstract class AbstractEntity {
  @PrimaryColumn({ type: 'uuid', default: () => 'uuidv7()' })
  id?: string;

  @CreateDateColumn({ type: 'timestamptz' })
  createdAt?: Date;

  @UpdateDateColumn({ type: 'timestamptz' })
  updatedAt?: Date;
}
